// The yard itself: a lit floor, a box per player, real props.
// The barrels are actual pack models - xp.load.model reads the glTF and
// .draw() feeds it to p5 with its own texture. The avatar's x/y are the
// ground plane.
var SPAN = 900

function drawFloor() {
  push()
  translate(0, 60, 0)
  rotateX(HALF_PI)
  noStroke()
  fill(24, 18, 52)
  plane(SPAN, SPAN)
  pop()
}

// A steady colour from an id, so everybody agrees who is which.
function hueOf(id) {
  var n = 0
  for (var i = 0; i < id.length; i += 1) n = (n * 31 + id.charCodeAt(i)) % 360
  return n
}

function drawPlayer(p) {
  var a = p.avatar
  // The player's real peep, drawn from the pack - their own skin when they
  // picked one. Standing in bind pose; the waddle below is procedural, and
  // real clip playback is the engine's next trick, not this sketch's.
  var look = xp.load.model(p.skin || 'peepz/bunny')
  var input = p.input
  var moving = abs(input.x) + abs(input.y) > 0.05
  push()
  translate(a.x, 60, a.y)
  rotateY(-a.angle + HALF_PI)
  if (look.ready) {
    // The waddle: a hop and a little roll while walking, a slow breath at rest.
    translate(0, moving ? -abs(sin(millis() / 90)) * 14 : sin(millis() / 600) * 2, 0)
    if (moving) rotateZ(sin(millis() / 90) * 0.08)
    scale(60)
    noStroke()
    fill(235)
    look.draw()
  } else {
    translate(0, -60, 0)
    noStroke()
    colorMode(HSB, 360, 100, 100)
    fill(p.you ? 190 : hueOf(p.id), 70, 95)
    colorMode(RGB, 255)
    box(60, 120, 60)
  }
  pop()
}

function drawProp(prop, x, z, size) {
  if (!prop.ready) return
  push()
  translate(x, 60, z)
  scale(size, size, size)
  noStroke()
  fill(220)
  prop.draw()
  pop()
}

