// A 3D yard in p5's WEBGL mode. Same xp.input, same synced avatar,
// same ball - plus real pack models standing in the corners. Boost with
// E or the button.
var ball
var barrel
var crate

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL)
  ball = xp.object('ball', { x: 0, y: 0 })
  barrel = xp.load.model('proto/Barrel_A')
  crate = xp.load.model('proto/Box_A')
  xp.avatar.x = random(-240, 240)
  xp.avatar.y = random(-240, 240)
}

function windowResized() { resizeCanvas(windowWidth, windowHeight) }

function draw() {
  background(4, 2, 16)
  ambientLight(90)
  directionalLight(255, 230, 200, -0.5, 1, -0.3)
  camera(0, -430, 640, 0, 0, 0, 0, 1, 0)
  walk()
  chase()
  drawFloor()
  var edge = SPAN / 2 - 80
  drawProp(barrel, -edge, -edge, 60)
  drawProp(barrel, edge, -edge, 60)
  drawProp(barrel, -edge, edge, 60)
  drawProp(barrel, edge, edge, 60)
  drawProp(crate, 0, -edge, 70)
  xp.players.forEach(drawPlayer)
  push()
  translate(ball.x, 20, ball.y)
  noStroke()
  fill(255, 214, 90)
  sphere(32)
  pop()
}

function walk() {
  var pace = xp.pressed('boost') ? 9 : 4.5
  xp.avatar.x = constrain(xp.avatar.x + xp.input.x * pace, -SPAN / 2, SPAN / 2)
  xp.avatar.y = constrain(xp.avatar.y + xp.input.y * pace, -SPAN / 2, SPAN / 2)
  if (xp.input.x !== 0 || xp.input.y !== 0) xp.avatar.angle = atan2(xp.input.y, xp.input.x)
}

function chase() {
  if (dist(xp.avatar.x, xp.avatar.y, ball.x, ball.y) < 80) ball.claim()
  if (ball.mine) {
    var away = atan2(ball.y - xp.avatar.y, ball.x - xp.avatar.x)
    ball.x = constrain(ball.x + cos(away) * 6, -SPAN / 2, SPAN / 2)
    ball.y = constrain(ball.y + sin(away) * 6, -SPAN / 2, SPAN / 2)
  }
}
